window.ZIYUAN={meta:{title:"Ziyuan",plot:1,total:window.ZIYUAN_PARTS.reduce((n,p)=>n+p.length,0)},seedMems:{"的":[{"text":"A white 白 ladle scooping possession — everything can be 的-owned.","adult":false,"votes":12}],"是":[{"text":"日 + 正 vibes: the sun is exactly this. 是 = is.","adult":false,"votes":8}],"不":[{"text":"A bird that refuses to fly up — one stroke blocks the sky. 不 = no.","adult":false,"votes":15}],"我":[{"text":"A hand with a spear defending the ego. That's me. 我.","adult":false,"votes":11}],"一":[{"text":"The horizon. One line to rule them all.","adult":false,"votes":20}],"有":[{"text":"A moon 月 wearing a hat — it *has* cover. 有 = have.","adult":false,"votes":7}],"人":[{"text":"Two legs walking. That's a person. Keep it dumb.","adult":false,"votes":18}],"大":[{"text":"A person 人 stretching both arms: BIG.","adult":false,"votes":9}],"在":[{"text":"Earth 土 with a talent 才 parked on it — you are *at* that plot.","adult":false,"votes":6}],"了":[{"text":"A hook that already caught the fish. Done. 了.","adult":false,"votes":10}],"國":[{"text":"Jade 玉 fenced in 囗 — the nation's treasure inside the walls.","adult":false,"votes":9}],"來":[{"text":"A tree waving you over. Come. 來.","adult":false,"votes":5}],"臺":[{"text":"Reach 至 a high terrace 高-ish platform. 臺 = platform / Taiwan.","adult":false,"votes":8}],"灣":[{"text":"Water 氵 plus a curved inlet. A bay. 臺灣 is the bay-terrace.","adult":false,"votes":7}],"捷":[{"text":"A quick hand 扌 that already arrived. 捷運 = the quick transport.","adult":false,"votes":6}],"垃":[{"text":"Trash that sounds like 'luh-suh' in Taipei, not 'lah-jee'. Plant this reading.","adult":false,"votes":14}],"車":[{"text":"A carriage seen from above: axle through a box. 車.","adult":false,"votes":8}],"吃":[{"text":"Mouth 口 begging 乞 for food. 吃.","adult":false,"votes":13}],"你":[{"text":"A person 亻 plus 尔 (you, classical). That's you.","adult":false,"votes":7}],"朕":[{"text":"皇帝把「我」換成「朕」，房間裡只准一個第一人稱。","adult":false,"votes":9}],"爻":[{"text":"一根全線、一根斷線。六次疊起來，《易》就開始算了。","adult":false,"votes":7}],"饕":[{"text":"一張青銅獸臉，專吃不完。下半截叫餮，兩字才成妖。","adult":false,"votes":8}],"餮":[{"text":"饕的下巴。單獨出現像少了一半的晚餐。","adult":false,"votes":6}],"魑":[{"text":"山鬼。後面還排著魅、魍、魎——鬼也要成軍才嚇人。","adult":false,"votes":6}],"魍":[{"text":"水邊木石怪。和魎綁在一起，不單獨出門。","adult":false,"votes":5}],"歟":[{"text":"文言的「嗎」，穿長袍。句子結尾一頓，像把杯子放回案上。","adult":false,"votes":5}],"脩":[{"text":"一束乾肉。孔門學費叫束脩——老師收肉，不收轉帳。","adult":false,"votes":10}],"艸":[{"text":"草還在畫根的時代。部首還用這張臉，葉子還沒長齊。","adult":false,"votes":7}],"匕":[{"text":"湯匙躺著，尖端一轉就成匕首。吃飯和刺人共用一個象形。","adult":false,"votes":8}],"驛":[{"text":"馬跑累了換一匹。唐詩用「驛」當公里數。","adult":false,"votes":6}],"稷":[{"text":"穀神。旁邊站著社（土神），兩個合寫就是國家。","adult":false,"votes":7}],"俎":[{"text":"砧板。越俎代庖：跑去切別人板上的肉。","adult":false,"votes":6}],"鸞":[{"text":"鳳的表親。鏡子叫鸞鏡，是因為鳳鳥喜歡對影。","adult":false,"votes":5}]},chars:window.ZIYUAN_PARTS.flat()};
